package no.bangerfabrikken.blockparty.arena;
import net.minecraft.ChatFormatting;import net.minecraft.core.component.DataComponents;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.SimpleMenuProvider;import net.minecraft.world.entity.player.Inventory;import net.minecraft.world.entity.player.Player;import net.minecraft.world.inventory.*;import net.minecraft.world.item.*;import net.minecraft.world.item.component.ItemLore;import java.util.*;
final class CosmeticsMenu extends ChestMenu{
 private final ServerPlayer viewer;private final CosmeticsManager.Category category;private final boolean mine;private final SimpleContainer contents;
 private static final int[] SLOTS={10,11,12,13,14,15,16,19,20,21,22,23,24,25};
 private CosmeticsMenu(int id,Inventory inv,ServerPlayer p,CosmeticsManager.Category cat,boolean my,SimpleContainer c){super(MenuType.GENERIC_9x6,id,inv,c,6);viewer=p;category=cat;mine=my;contents=c;ItemStack filler=item(Items.BLACK_STAINED_GLASS_PANE," ");for(int s=0;s<54;s++)c.setItem(s,filler.copy());put(4,Items.NETHER_STAR,my?"MINE KOSMETIKK":"KOSMETIKKBUTIKK","Poeng: "+PlayerStatsManager.getPoints(p.getUUID()));
 if(cat==null&&!my){put(20,Items.FIREWORK_STAR,"TRAILS","Partikler som følger deg");put(22,Items.DIAMOND_CHESTPLATE,"ARMOR","Kosmetisk rustning");put(24,Items.BELL,"KILL SOUNDS","Lyder ved eliminering");put(30,Items.FEATHER,"FOOTSTEPS","Lyder når du går");put(32,Items.CHEST,"MY COSMETICS","Alt du eier og har utstyrt");}
 else{Collection<CosmeticsManager.Cosmetic> list=my?CosmeticsManager.owned(p.getUUID()):CosmeticsManager.items(cat);int i=0;for(var x:list){if(i>=SLOTS.length)break;boolean owned=CosmeticsManager.owns(p.getUUID(),x.id());boolean eq=x.id().equals(CosmeticsManager.equipped(p.getUUID(),x.category()));c.setItem(SLOTS[i++],item(net.minecraft.core.registries.BuiltInRegistries.ITEM.byId(x.icon()),x.name(),x.description(),owned?"EIES":"Pris: "+x.price()+" poeng",eq?"UTSTYRT":"Klikk for å kjøpe / utstyre"));}put(49,Items.ARROW,"TILBAKE","Til kategoriene");put(45,Items.BARRIER,"FJERN UTSTYR","Fjern kosmetikken i denne kategorien");}
 put(53,Items.BARRIER,"LUKK","Lukk menyen");}
 static void open(ServerPlayer p,CosmeticsManager.Category c){open(p,c,false);}static void open(ServerPlayer p,CosmeticsManager.Category c,boolean mine){p.openMenu(new SimpleMenuProvider((id,inv,v)->new CosmeticsMenu(id,inv,(ServerPlayer)v,c,mine,new SimpleContainer(54)),Component.literal("BlockParty Kosmetikk")));}
 private static ItemStack item(Item item,String name,String... lore){ItemStack s=new ItemStack(item);s.set(DataComponents.CUSTOM_NAME,Component.literal(name).withStyle(ChatFormatting.YELLOW,ChatFormatting.BOLD));s.set(DataComponents.LORE,new ItemLore(Arrays.stream(lore).map(x->Component.literal(x).withStyle(ChatFormatting.GRAY)).toList()));return s;}
 private void put(int slot,Item item,String name,String lore){contents.setItem(slot,item(item,name,lore));}
 @Override public void clicked(int slot,int button,ClickType type,Player p){if(p!=viewer||type!=ClickType.PICKUP||button!=0||slot<0||slot>=54)return;if(slot==53){viewer.closeContainer();return;}if(category==null&&!mine){if(slot==20)open(viewer,CosmeticsManager.Category.TRAILS);else if(slot==22)open(viewer,CosmeticsManager.Category.ARMOR);else if(slot==24)open(viewer,CosmeticsManager.Category.KILL_SOUNDS);else if(slot==30)open(viewer,CosmeticsManager.Category.FOOTSTEPS);else if(slot==32)open(viewer,null,true);return;}if(slot==49){open(viewer,null);return;}if(slot==45&&category!=null){CosmeticsManager.unequip(viewer,category);open(viewer,category);return;}Collection<CosmeticsManager.Cosmetic> list=mine?CosmeticsManager.owned(viewer.getUUID()):CosmeticsManager.items(category);for(int i=0;i<Math.min(SLOTS.length,list.size());i++)if(SLOTS[i]==slot){CosmeticsManager.select(viewer,list.stream().skip(i).findFirst().orElseThrow().id());open(viewer,category,mine);return;}}
}
